from typing import Any, Deque, Dict, List, Union

def decode_deque(d: Deque[Any]) -> Any:
    """
    Recursively decode a deque into standard Python types.
    - deque -> list
    - dict values are decoded
    - list/tuple elements are decoded
    Other types are returned as-is.
    """
    if isinstance(d, deque):
        return [decode_deque(x) for x in d]
    if isinstance(d, dict):
        return {k: decode_deque(v) for k, v in d.items()}
    if isinstance(d, list):
        return [decode_deque(x) for x in d]
    if isinstance(d, tuple):
        return tuple(decode_deque(x) for x in d)
    return d


